# Explicit numeric conversions

```ghost
control ExplicitNumericConversions {
  let approximate = number(7);
  let exact = int_exact(7.0);
  let down = int_floor(1.9);
  let up = int_ceil(1.1);
  let toward_zero = int_trunc(-1.9);
  let nearest = int_nearest_even(2.5);
  output valid: Bool;
  valid <- approximate == 7.0 && exact == 7 && down == 1 && up == 2 && toward_zero == -1 && nearest == 2;
}
```

