# Exhaustive enum

```ghost
control ExhaustiveEnum {
  type Phase = Idle | Running;
  state phase: Phase = Idle;
  phase' = case phase {
    Idle => Running;
    Running => Idle;
  };
}
```

# Missing enum case

```ghost
control MissingEnumCase {
  type Phase = Idle | Running;
  state phase: Phase = Idle;
  phase' = case phase {
    Idle => Running;
  };
}
```

# Branch type mismatch

```ghost
control BranchMismatch {
  type Phase = Idle | Running;
  state phase: Phase = Idle;
  let invalid = case phase {
    Idle => true;
    Running => 1.0;
  };
}
```

# Enum membership

```ghost
control EnumMembership {
  type Phase = Idle | Opening | Running;
  state phase: Phase = Idle;
  output active: Bool;
  active <- phase in {Opening, Running};
}
```

